<?php

namespace App\Models;

use App\Enums\Unit;
use App\Enums\UnitGroup;
use App\Support\Quantity;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;

/**
 * A shopping list line (DATA-MODEL §2): generated by closing the menu or added manually.
 *
 * @property int $id
 * @property int $shopping_list_id
 * @property string $origin
 * @property int|null $ingredient_id
 * @property string $name
 * @property numeric-string|null $quantity
 * @property Unit|null $unit
 * @property UnitGroup|null $unit_group
 * @property string|null $match_key
 * @property numeric-string|null $calculated_quantity
 * @property Unit|null $calculated_unit
 * @property int|null $receptions_counted_after
 * @property bool $is_user_modified
 * @property bool $is_dismissed
 * @property bool $is_purchased
 * @property bool $needs_review
 * @property string|null $review_reason
 */
#[Fillable([
    'shopping_list_id', 'origin', 'ingredient_id', 'name', 'quantity', 'unit', 'unit_group', 'match_key',
    'calculated_quantity', 'calculated_unit', 'receptions_counted_after', 'is_user_modified', 'is_dismissed', 'is_purchased',
    'needs_review', 'review_reason',
])]
class ShoppingListItem extends Model
{
    public const GENERATED = 'generated';

    public const MANUAL = 'manual';

    /**
     * @return BelongsTo<ShoppingList, $this>
     */
    public function shoppingList(): BelongsTo
    {
        return $this->belongsTo(ShoppingList::class);
    }

    /**
     * @return BelongsTo<Ingredient, $this>
     */
    public function ingredient(): BelongsTo
    {
        return $this->belongsTo(Ingredient::class);
    }

    /**
     * @return HasMany<ReceptionItem, $this>
     */
    public function receptionItems(): HasMany
    {
        return $this->hasMany(ReceptionItem::class);
    }

    public function isGenerated(): bool
    {
        return $this->origin === self::GENERATED;
    }

    public function toQuantity(): ?Quantity
    {
        return $this->quantity !== null && $this->unit !== null ? Quantity::of($this->quantity, $this->unit) : null;
    }

    public function calculated(): ?Quantity
    {
        return $this->calculated_quantity !== null && $this->calculated_unit !== null
            ? Quantity::of($this->calculated_quantity, $this->calculated_unit)
            : null;
    }

    public function setQuantity(?Quantity $quantity): void
    {
        $quantity = $quantity?->storable();
        $this->quantity = $quantity?->amount;
        $this->unit = $quantity?->unit;
        $this->unit_group = $quantity?->unit->group();
    }

    public function setCalculated(?Quantity $quantity): void
    {
        $quantity = $quantity?->storable();
        $this->calculated_quantity = $quantity?->amount;
        $this->calculated_unit = $quantity?->unit;
    }

    public function flagForReview(string $reason): void
    {
        $this->needs_review = true;
        $this->review_reason = $reason;
    }

    /**
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'quantity' => 'decimal:3',
            'unit' => Unit::class,
            'unit_group' => UnitGroup::class,
            'calculated_quantity' => 'decimal:3',
            'calculated_unit' => Unit::class,
            'is_user_modified' => 'boolean',
            'is_dismissed' => 'boolean',
            'is_purchased' => 'boolean',
            'needs_review' => 'boolean',
        ];
    }
}
